@WithJenkins
@ExtendWith(MockServerExtension.class)
 class GitLabCommitStatusPublisherTest {}
/**************TEST SETUP BEGIN*************/
@BeforeEach
void setUp(){
    listener = new StreamBuildListener(jenkins.createTaskListener().getLogger(), Charset.defaultCharset());
}
@BeforeAll
static void setUp(JenkinsRule rule, MockServerClient client) throws Exception{
    jenkins = rule;
    mockServerClient = client;
    setupGitLabConnections(jenkins, client);
}
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
void running_multipleRepos(){
    AbstractBuild build = mockBuild(GITLAB_CONNECTION_V4, null, "test/project-1.git", "test/project-2.git");
    HttpRequest[] requests = new HttpRequest[] { prepareExistsCommitWithSuccessResponse("v4", "test/project-1"), prepareUpdateCommitStatusWithSuccessResponse("v4", "test/project-1", build, BuildState.running), prepareExistsCommitWithSuccessResponse("v4", "test/project-2"), prepareUpdateCommitStatusWithSuccessResponse("v4", "test/project-2", build, BuildState.running) };
    prebuildAndVerify(build, listener, requests);
}
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private HttpRequest prepareExistsCommitWithSuccessResponse(String apiLevel, String projectName){
        HttpRequest existsCommit = prepareExistsCommit(apiLevel, projectName);
        mockServerClient.when(existsCommit).respond(response().withStatusCode(200));
        return existsCommit;
    }
private HttpRequest prepareExistsCommit(String apiLevel, String projectName){
        return request().withPath("/gitlab/api/" + apiLevel + "/projects/" + URLEncoder.encode(projectName, StandardCharsets.UTF_8) + "/repository/commits/" + SHA1).withMethod("GET").withHeader("PRIVATE-TOKEN", "secret");
    }
/**************TEST HELPER METHOD END*************/
/**************TEST TEARDOWN BEGIN*************/
@AfterEach
void tearDown(){
    mockServerClient.reset();
}
/**************TEST TEARDOWN END*************/


